source='''from collections import Counter

def _runs(line, bg):
    out = []
    i = 0
    while i < len(line):
        if line[i] == bg:
            i += 1
            continue
        color = line[i]
        j = i + 1
        while j < len(line) and line[j] == color:
            j += 1
        out.append((i, j, color))
        i = j
    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    out = [row[:] for row in grid]
    pairs = []
    for side_a, side_b, length in ((grid[0], grid[-1], w), ([grid[r][0] for r in range(h)], [grid[r][-1] for r in range(h)], h)):
        for a in _runs(side_a, bg):
            for b in _runs(side_b, bg):
                if a[2] == b[2] and (a[1]-a[0]) == (b[1]-b[0]):
                    pairs.append((a, b, a[2], length))
    for a, b, rail, axis_len in pairs:
        # Markers whose coordinate falls within either matching edge segment select a lane offset.
        marker_offsets = {}
        for r in range(h):
            for c in range(w):
                val = grid[r][c]
                if val == bg or val == rail:
                    continue
                for seg in (a, b):
                    coord = c if axis_len == w else r
                    if seg[0] <= coord < seg[1]:
                        marker_offsets.setdefault(coord-seg[0], set()).add(val)
        for offset, colors in marker_offsets.items():
            for seg, side in ((a, 0), (b, 1)):
                coord = seg[0] + offset
                if coord >= seg[1]:
                    continue
                # A marker sets the color of the projected rail; the endpoint changes to 4.
                color = min(colors)
                if axis_len == w:
                    # top/bottom boundary runs project vertically
                    start = 1 if side == 0 else h-2
                    step = 1 if side == 0 else -1
                    r = start
                    while 0 <= r < h:
                        if grid[r][coord] not in (bg, rail):
                            out[r][coord] = 4
                            break
                        out[r][coord] = color
                        r += step
                else:
                    # left/right boundary runs project horizontally
                    start = 1 if side == 0 else w-2
                    step = 1 if side == 0 else -1
                    c = start
                    while 0 <= c < w:
                        if grid[coord][c] not in (bg, rail):
                            out[coord][c] = 4
                            break
                        out[coord][c] = color
                        c += step
    return out
